        JsonNode root;
        try {
            root = mapper.readTree(ctx.body());
        } catch (Exception e) {
            throw invalid("Corpo da requisição não é um JSON válido");
        }
        if (root == null || !root.isObject()) throw invalid("Corpo da requisição deve ser um objeto JSON");

