        assertEquals("CANCELLED", ca.get("status").asText());
        assertEquals(0.0, ca.get("refund").asDouble());
        // a data liberou-se
        long b = call("POST", "/reservations", req(301, "b@x.com", "2028-05-01", "2028-05-03", 1, "STANDARD")).json().get("id").asLong();
